/// Look up a class layout by exact retail class name.
pub fn lookup(name: &str) -> Option<&'static ClassLayout> {
    ALL.iter().copied().find(|c| c.name == name)
}

/// Fields of `layout` covering byte range `start..end` (relative to
/// the class image). Returns the overlapping field names, deduplicated.
pub fn fields_covering(layout: &ClassLayout, start: usize, end: usize) -> Vec<&'static str> {
    let mut v: Vec<&'static str> = layout.fields.iter()
        .filter(|f| (f.off as usize) < end && (f.off as usize + f.size as usize) > start)
        .map(|f| f.name)
        .collect();
    v.dedup();
    v
}
